const express = require('express');
const { verifyApiKey } = require('../auth');
const ServerModel = require('../models/Server');

const router = express.Router();

router.get('/api/metrics/:serverId/chunked-stream', verifyApiKey, async (req, res) => {
  const { serverId } = req.params;

  const server = await ServerModel.findOne({
    _id: serverId,
    orgId: req.apiKeyData.orgId
  });
  if (!server) {
    return res.status(403).json({ error: 'Forbidden: server not found or access denied' });
  }

  res.writeHead(200, {
    'Content-Type': 'text/plain',
    'Transfer-Encoding': 'chunked',
  });

  const interval = setInterval(() => {
    const temp = (45 + Math.random() * 10).toFixed(1);
    res.write(`server=${serverId} temp=${temp}C fan=2400rpm\n`);
  }, 2000);

  req.on('close', () => clearInterval(interval));
});
